<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue';
import { v1 } from '../api';
import type { MemoryProjectView } from '../../contracts/memory';
import MarkdownText from './MarkdownText.vue';
import UiSelect from './UiSelect.vue';
const projects=ref<Array<MemoryProjectView&{hasIndex:boolean}>>([]),projectId=ref(''),query=ref(''),selected=ref(''),content=ref(''),hash=ref(''),error=ref(''),message=ref(''),loading=ref(false),reading=ref(false),saving=ref(false),editing=ref(false);
let generation=0,disposed=false;
const project=computed(()=>projects.value.find(p=>p.id===projectId.value));
const files=computed(()=>{const list=project.value?.files??[];const index=project.value?.hasIndex?[{filename:'MEMORY.md',description:'记忆索引',type:'index',mtimeMs:0,sizeBytes:0}]:[];return [...index,...list].filter(f=>`${f.filename} ${f.description??''}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase()));});
async function load(){loading.value=true;error.value='';try{const data=await v1<{projects:Array<MemoryProjectView&{hasIndex:boolean}>}>('/api/v1/memory');if(disposed)return;projects.value=data.projects;if(!projects.value.some(p=>p.id===projectId.value))projectId.value=projects.value[0]?.id??'';}catch(e){if(!disposed)error.value=e instanceof Error?e.message:'记忆读取失败';}finally{if(!disposed)loading.value=false;}}
function chooseProject(value:string|number){generation++;projectId.value=String(value);selected.value='';content.value='';editing.value=false;reading.value=false;error.value='';}
async function read(path:string){const ticket=++generation;reading.value=true;error.value='';message.value='';selected.value=path;content.value='';hash.value='';editing.value=false;const id=projectId.value;try{const result=await v1<{content:string;hash:string}>(`/api/v1/projects/${id}/memory/file?path=${encodeURIComponent(path)}`);if(!disposed&&ticket===generation&&id===projectId.value){content.value=result.content;hash.value=result.hash;}}catch(e){if(ticket===generation)error.value=e instanceof Error?e.message:'记忆内容读取失败';}finally{if(ticket===generation)reading.value=false;}}
async function save(){if(saving.value||!selected.value)return;saving.value=true;error.value='';try{await v1(`/api/v1/projects/${projectId.value}/memory/file`,{method:'PUT',body:JSON.stringify({path:selected.value,content:content.value,expectedHash:hash.value})});await read(selected.value);await load();message.value='已保存并更新索引';}catch(e){error.value=e instanceof Error?e.message:'保存失败，请重新读取最新版本后合并';}finally{saving.value=false;}}
onMounted(()=>void load());onBeforeUnmount(()=>{disposed=true;generation++;});
</script>
<template>
 <section class="memory-settings"><p class="settings-description">按项目查看跨任务记忆。记忆可能过时，恢复工作时仍需核对当前文件与来源版本。自动召回和回合后提炼会产生模型用量，可在“Agent 与上下文”关闭记忆功能。</p><div class="memory-toolbar"><UiSelect :model-value="projectId" :options="projects.map(p=>({value:p.id,label:p.name}))" label="记忆所属项目" :disabled="saving" @change="chooseProject"/><input v-model="query" type="search" placeholder="搜索记忆文件或描述" aria-label="搜索记忆"/><button type="button" class="btn" :disabled="loading||saving" @click="load">{{loading?'正在刷新…':'刷新'}}</button></div>
 <p v-if="error" role="alert" class="memory-error">{{error}}</p><p v-if="message" role="status">{{message}}</p><p v-if="!loading&&!projects.length">还没有项目。</p><p v-else-if="!loading&&!files.length">{{query?'没有匹配的记忆。':'这个项目暂无记忆。可在对话中要求 Agent 记住信息或保存项目交接。'}}</p>
 <div v-if="files.length" class="memory-layout"><ul class="memory-list" aria-label="项目记忆列表"><li v-for="file in files" :key="file.filename"><button type="button" :class="{selected:selected===file.filename}" :disabled="saving" @click="read(file.filename)"><strong>{{file.filename}}</strong><span>{{file.description||file.type||'记忆文件'}}</span><small v-if="file.mtimeMs">{{new Date(file.mtimeMs).toLocaleString()}}</small></button></li></ul><section class="memory-preview" aria-label="记忆内容"><p v-if="reading" role="status">正在读取…</p><template v-else-if="selected&&hash"><header><strong>{{selected}}</strong><button type="button" class="btn" :disabled="saving" @click="editing=!editing">{{editing?'查看预览':'编辑'}}</button><button v-if="editing" type="button" class="btn btn-solid" :disabled="saving" @click="save">{{saving?'正在保存…':'保存'}}</button></header><textarea v-if="editing" v-model="content" aria-label="编辑记忆内容" :disabled="saving"/><MarkdownText v-else :text="content"/></template><p v-else>选择一条记忆查看内容。</p></section></div></section>
</template>
<style scoped>
.memory-settings{min-width:0}.memory-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.memory-toolbar input{flex:1;min-width:160px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--bg-input);color:var(--fg);font:inherit}.memory-layout{display:grid;grid-template-columns:minmax(180px,32%) minmax(0,1fr);gap:16px;margin-top:16px}.memory-list{list-style:none;margin:0;padding:0;max-height:60vh;overflow:auto}.memory-list button{display:grid;gap:4px;text-align:left;width:100%;padding:10px;border:0;border-radius:8px;background:transparent;color:var(--fg);cursor:pointer;overflow-wrap:anywhere}.memory-list button:hover{background:var(--hover)}.memory-list button.selected{background:var(--selected)}.memory-list strong{font-weight:500}.memory-list span,.memory-list small{color:var(--fg-subtle);font-size:var(--text-ui-sm)}.memory-preview{min-width:0;border:1px solid var(--border);border-radius:10px;padding:14px;max-height:65vh;overflow:auto;overscroll-behavior:contain}.memory-preview header{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.memory-preview header strong{flex:1;overflow-wrap:anywhere}.memory-preview textarea{box-sizing:border-box;width:100%;min-height:320px;font:inherit;line-height:1.6;background:var(--bg-input);color:var(--fg);border:1px solid var(--border);padding:10px;border-radius:6px}.memory-error{color:var(--danger)}@media(max-width:650px){.memory-layout{grid-template-columns:1fr}.memory-list{max-height:200px}}
</style>
